import pathlib,csv,json,re
root=pathlib.Path.cwd();errors=[]
rows=list(csv.DictReader((root/'@prime/UI_MODULES.csv').open(encoding='utf-8-sig',newline='')))
ids={r['module_id'] for r in rows}
if len(ids)!=len(rows):errors.append('duplicate module ID')
for r in rows:
 if r['path_state']=='EXISTING' and not (root/r['path']).exists(): errors.append('missing path '+r['path'])
 for d in filter(None,r['depends_on_modules'].split(';')):
  if d not in ids:errors.append('missing module dependency '+d)
 phase=(root/'@prime/UI_PHASES.md').read_text(encoding='utf-8')
 for task in filter(None,r['ui_tasks'].split(';')):
  if task not in phase:errors.append('missing task '+task)
 plan,anchor=r['plan_anchor'].split('#',1)
 headings=re.findall(r'^#{1,6} (.+)$',(root/'@prime'/plan).read_text(encoding='utf-8'),re.M)
 if anchor not in {re.sub(r'[^\w\- ]','',h.lower()).replace(' ','-') for h in headings}:errors.append('missing plan anchor '+anchor)
sources='\n'.join(f.read_text(encoding='utf-8') for base in [root/'apps/polaris-cli',root/'crates/polaris-ui',root/'crates/polaris-kernel/crates/directives'] for f in base.rglob('*.rs'))
files=list((root/'specs/descriptors').glob('ui*.json'))+[root/'apps/polaris-cli/specs/descriptors/headless_cli.json']
count=0
for file in files:
 data=json.loads(file.read_text(encoding='utf-8'))
 for test in data['test_list']:
  count+=1
  if not re.search(r'\bfn\s+'+re.escape(test['test_name'])+r'\b',sources):errors.append(file.name+': missing '+test['test_name'])
print(json.dumps({'inventory_modules':len(rows),'unique_ids':len(ids),'descriptors':len(files),'test_references':count,'errors':errors},indent=2))
raise SystemExit(bool(errors))
